begin; select plan(13);
insert into auth.users(id,email) values('00000000-0000-0000-0000-00000000000a','a@t'),('00000000-0000-0000-0000-00000000000b','b@t');
set local role authenticated; set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-00000000000a"}';
create temp table ctx as select create_family_with_defaults('Keluarga A') fid;
insert into wallets(family_id,name,kind) select fid,'W','cash' from ctx;
insert into transactions(family_id,type,date,amount,wallet_id,category_id) select c.fid,'expense',current_date,10,(select id from wallets limit 1),(select id from categories where type='expense' limit 1) from ctx c;
insert into budgets(family_id,scope,category_id,period_type,start_date,end_date,amount) select c.fid,'category',(select id from categories where type='expense' limit 1),'monthly',current_date,current_date+30,100 from ctx c;
insert into assets(family_id,name,kind) select fid,'As','Emas' from ctx;
insert into debts(family_id,direction,counterparty,principal) select fid,'payable','X',100 from ctx;
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-00000000000b"}';
select is((select count(*) from families)::int,0,'B tidak melihat families milik A');
select is((select count(*) from family_members)::int,0,'B tidak melihat family_members milik A');
select is((select count(*) from wallets)::int,0,'B tidak melihat wallets milik A');
select is((select count(*) from categories)::int,0,'B tidak melihat categories milik A');
select is((select count(*) from transactions)::int,0,'B tidak melihat transactions milik A');
select is((select count(*) from budgets)::int,0,'B tidak melihat budgets milik A');
select is((select count(*) from assets)::int,0,'B tidak melihat assets milik A');
select is((select count(*) from debts)::int,0,'B tidak melihat debts milik A');
select is((select count(*) from recurring_transactions)::int,0,'B tidak melihat recurring_transactions milik A');
select is((select count(*) from audit_logs)::int,0,'B tidak melihat audit_logs milik A');
select throws_ok($$insert into wallets(family_id,name,kind) select fid,'X','cash' from ctx$$,'42501',null,'B tidak bisa menulis ke keluarga A');
select throws_ok($$select create_invitation((select fid from ctx),'member')$$,'42501',null,'B tidak bisa membuat undangan');
select is((with u as (update family_members set role='owner' returning 1) select count(*) from u)::int,0,'B tidak bisa mengubah role');
select * from finish(); rollback;